const data={bg:{nav:'СЪДЪРЖАНИЕ',aside:'',foot:'Ръководство за потребителя',items:['Какво е TaskTime','Къде работи','Как се засича задача','Кога задачата е завършена','Сигнали и цветен таб','Смяна, почивки, overtime','Въпросите в панела','Отчетът (Dashboard)','Данни и поверителност','Известни ограничения'],badge:'',title:'Твоят работен ден.<br><em>Ясно измерен.</em>',lead:'TaskTime е браузърна добавка за Chrome и Opera. Тя сама засича задачите, които правиш в Redstone, и смените ти в Ximble, и ти показва личен отчет: колко задачи, колко време на всяка, почивки и overtime. Всичко остава само в твоя браузър.',meta:['Google Chrome + Opera','Български / English','Без сървър · локални данни'],stats:[['4','бутона приключват задача'],['3','етапа на сигнала: 🟢 🟠 🔴'],['0','данни, изпратени навън']],sections:[
['Личен дневник, който се попълва сам.',`<p>Задачите в Redstone идват една след друга, а официалният отчет идва по-късно. TaskTime ти дава собствена, разбираема история още същия ден: какво си завършил, колко време ти е отнело всяко и как е минала смяната.</p><div class="cards"><div class="card"><span class="tag">ЗАДАЧИ</span><h3>Автоматично засичане</h3><p>Добавката разпознава задачата по адреса на страницата (лига, тип, ID) и мери времето, докато е отворена. Ти не натискаш нищо допълнително.</p></div><div class="card"><span class="tag">СМЯНА</span><h3>Работно време от Ximble</h3><p>Clock In и Clock Out в Ximble определят началото, почивките и края на смяната. Добавката пита само това, което не може да знае сама.</p></div><div class="card"><span class="tag">СИГНАЛИ</span><h3>Не изпускай задача</h3><p>Звук и цветна иконка на таба, когато излезе нова задача или когато Redstone пита „Are you still active?“.</p></div><div class="card"><span class="tag">ОТЧЕТ</span><h3>Статистика по тип</h3><p>Брой, най-бърза, най-бавна, средна и обща продължителност за всеки тип задача, за избран период, с износ в CSV.</p></div></div><div class="callout">Часовете в TaskTime са моментите, в които добавката е <strong>видяла</strong> събитието. Това е личен отчет, а не официалният таймер на работодателя. Малки разлики са нормални.</div>`],
['Два сайта, всеки със своята роля.',`<div class="cards"><div class="card"><span class="tag">01 / ЗАДАЧИ</span><h3>redstone.secondspectrum.com</h3><p>Задача се разпознава по адреса:</p><p><code>/global-tasks/&lt;лига&gt;/&lt;тип&gt;/&lt;ID&gt;</code></p><p>Пример: <code>/global-tasks/uefa/single_player/8c3b492f-…</code></p><ul><li><strong>Лига</strong>: всяка лига след <code>/global-tasks/</code> се приема, вкл. нови (dsl, efl, football, football-delayed, ligue1, ligue2, lkl, uefa…).</li><li><strong>Тип</strong>: ball, player, single_player, live_dead, lineup, reid, away, home, refs. Непознат тип се записва като <code>other</code>, не се губи.</li><li><strong>ID</strong>: букви, цифри, „-“ и „_“.</li></ul></div><div class="card"><span class="tag">02 / РАБОТНО ВРЕМЕ</span><h3>app.ximble.com</h3><p>Добавката гледа кой бутон се вижда: <strong>Clock Out</strong> видим = на смяна си; <strong>Clock In</strong> видим = не си на смяна.</p><p>Статусът се приема, след като е стабилен 2 секунди, за да не се хванат моменти на зареждане.</p></div></div><div class="callout"><strong>Страници, които НЕ са задачи:</strong> екранът за чакане <code>/global-tasks/&lt;лига&gt;/next</code> („no tasks available, waiting“) и менютата Config, Mercury, Generate, Filters, Summary, Timing, Queue. Други домейни (напр. redstone-dev) не се следят изобщо.</div><p>Двата сайта трябва да са отворени в <strong>един и същ браузър и профил</strong>, в който е инсталирана добавката. Дръж Ximble отворен в отделен таб през смяната.</p>`],
['От отваряне до край на задачата.',`<div class="flow"><div class="step"><h3>1. Задачата се отваря</h3><p>Щом адресът стане задача, започва запис: лига, тип, ID, начален момент. Auto Advance, кликовете и превъртането са действия вътре в същата задача.</p></div><div class="step"><h3>2. Времето се трупа</h3><p>Докато табът е отворен, на всеки 15 секунди добавката отбелязва, че задачата е още там. Ако между две отбелязвания минат над 45 секунди (компютърът заспал, браузърът спрял), времето НЕ се брои, а се записва „пропуск“.</p></div><div class="step"><h3>3. Натискаш бутон за край</h3><p>Един от четирите: <strong>Finish & Next</strong>, <strong>Finish & Exit</strong>, <strong>Clear Samples & Next</strong>, <strong>Clear Samples & Exit</strong>. Времето на задачата спира в момента на клика.</p></div><div class="step"><h3>4. Страницата напуска задачата</h3><p>Към следваща задача, към екрана за чакане или затваряне на таба. Ако това стане до 2 минути след клика, задачата е <strong>завършена</strong>.</p></div></div><div class="callout"><strong>Презареждане на страницата</strong> (напр. когато бутоните само се въртят и трябва refresh) не прекъсва задачата: адресът и ID-то са същите, времето продължава. Ако презареждането трае над 45 секунди, се записва пропуск.</div>`],
['Завършена или „за преглед“?',`<p>Всяка задача завършва с един от два статуса. Само <strong>завършените</strong> влизат в статистиката.</p><div class="cards"><div class="card"><span class="tag">✓ ЗАВЪРШЕНА</span><h3>Всичко е ясно</h3><ul><li>Натиснат е един от четирите бутона за край,</li><li>до 2 минути след това страницата е напуснала задачата,</li><li>няма пропуск над 45 секунди,</li><li>сайтът не е показал грешка след клика,</li><li>същата задача (същото ID) не е вече завършена по-рано.</li></ul></div><div class="card"><span class="tag">? ЗА ПРЕГЛЕД</span><h3>Нещо не е сигурно</h3><ul><li>Няма клик на бутон за край (напр. модератор е премахнал задачата и си натиснал обикновено Next/Exit),</li><li>напускане повече от 2 минути след клика,</li><li>пропуск във времето,</li><li>грешка от сайта,</li><li>същото ID отворено отново,</li><li>същата задача отворена в два таба.</li></ul><p>В отчета ги <strong>потвърждаваш</strong> или <strong>изключваш</strong> с един бутон. Корекцията се пази с оригиналната причина.</p></div></div><div class="callout">Иконката на добавката показва „!“, когато има задачи за преглед.</div>`],
['Звук и цвят, когато трябва да погледнеш.',`<p>Добавката сменя иконката и заглавието на таба с Redstone и пуска кратък двутонален сигнал. Иконата и заглавието се връщат нормални веднага щом сигналът спре.</p><div class="table-wrap"><table><thead><tr><th>Етап</th><th>Кога</th><th>Таб</th><th>Звук</th><th>Спира</th></tr></thead><tbody><tr><td>🟢 Зелено</td><td>Нова задача, докато табът НЕ е на фокус</td><td>зелен кръг, мига „🟢 New task“</td><td>1 сигнал</td><td>като се върнеш в таба</td></tr><tr><td>🟠 Оранжево</td><td>Redstone показва „Are you still active?“</td><td>оранжев кръг, „🟠 Not Active 13 sec.“</td><td>1 сигнал / сек.</td><td>прозорецът изчезне</td></tr><tr><td>🔴 Червено</td><td>Остават 5 секунди или по-малко</td><td>червен кръг, „🔴 Not Active 4 sec.“</td><td>2 сигнала / сек.</td><td>прозорецът изчезне</td></tr></tbody></table></div><p class="caption">„На фокус“ значи: табът е активен И прозорецът на браузъра е най-отгоре. Минимизиран браузър, друг таб или друга програма = не е на фокус.</p><div class="cards" style="margin-top:20px"><div class="card"><h3>Настройки (в отчета)</h3><ul><li><strong>Звуков сигнал</strong> — вкл./изкл. (по подразбиране вкл.). Изключва само звука; цветът на таба остава.</li><li><strong>Сила на звука</strong> и бутон <strong>„Пробвай звука“</strong>.</li><li><strong>Известие в системата</strong> — по подразбиране изкл. При включване браузърът иска разрешение. Показва лига и тип; клик те връща в таба.</li></ul></div><div class="card"><h3>Как се засича „Are you still active?“</h3><p>По текста на прозореца, а секундите се четат от „…in <strong>13</strong> seconds“. Работи и по средата на задача, не само след нова. Оранжевото и червеното звучат дори ако прозорецът е на фокус — ако не реагираш, вероятно не си на компютъра.</p></div></div>`],
['Една логическа смяна, с всички прекъсвания.',`<div class="flow"><div class="step"><h3>Clock In</h3><p>Започва смяна. Добавката пита „До колко часа е смяната ти?“. При нощни смени (20:00 → 02:00) краят автоматично е на следващия ден и се показва датата.</p></div><div class="step"><h3>Clock Out</h3><p>Въпрос: „Почивка или приключваш работа?“. <strong>Почивка</strong>: смяната продължава, следващият Clock In я подновява. <strong>Приключвам</strong>: смяната се затваря в момента на Clock Out.</p></div><div class="step"><h3>Планираният край мине</h3><p>Ако още си Clock In: „Планираната ти смяна приключи. Още ли работиш?“ → <strong>Продължавам с overtime</strong> или <strong>Приключвам</strong>.</p></div><div class="step"><h3>„Приключвам“ без Clock Out</h3><p>Напомняне: „Направи Clock Out в Ximble, за да се потвърди краят.“ Смяната никога не се затваря само по часовник.</p></div></div><div class="callout">Отговорът може да дойде по-късно: записва се часът на <strong>събитието</strong>, не на отговора. Ако си отговорил „Приключвам“ след като вече си се върнал на работа, по-новият период става отделна смяна. Ако отвориш Ximble, когато смяната вече е започнала, началото е моментът, в който добавката я е видяла.</div><p><strong>Иконката на добавката</strong> показва статуса: 🟢 зелена = на смяна, 🟠 оранжева = почивка, 🔴 червена = извън смяна. Число върху нея = чакащи въпроси.</p>`],
['Въпросът остава, докато отговориш.',`<p>Въпросите се показват в малък панел в горния ляв ъгъл на Redstone и Ximble, и в отчета. Панелът не отнема фокуса и не пречи на работата — може да отговориш, когато ти е удобно.</p><div class="panel"><strong>Почивка или приключваш работа?</strong><p>Въпросът остава, докато отговориш. Часът на събитието е запазен.</p><div class="actions"><span class="example-action">Почивка</span><span class="example-action">Приключвам</span></div></div><p>Видове въпроси: краен час на смяната, почивка/край при Clock Out, overtime след планирания край, напомняне за Clock Out. Бутонът „Отчет“ в панела отваря пълния отчет.</p>`],
['Всичко на едно място.',`<p>Клик върху иконката TaskTime в лентата на браузъра отваря отчета. Той има:</p><div class="cards"><div class="card"><h3>Сигнал за нова задача</h3><p>Настройки на звука и известията (виж по-горе).</p></div><div class="card"><h3>Статистика</h3><p>Избираш период (от–до). За всеки тип: брой, най-бърза, най-бавна, средно, общо. Броят се само завършени задачи, по датата на завършване.</p></div><div class="card"><h3>Смени</h3><p>Начало, край, работно време, почивки, планиран край и време след него, дали си избрал overtime.</p></div><div class="card"><h3>За преглед + История</h3><p>Неясните задачи с бутони „Потвърди“/„Изключи“, и пълен списък на всички задачи с ID, време и брой пропуски.</p></div></div>${report('bg')}<p style="margin-top:18px"><strong>Износ:</strong> <em>CSV</em> със статистиката за периода (отваря се в Excel, с часова зона) и <em>JSON архив</em> с всички данни. Средно = общо време ÷ брой завършени. Езикът (БГ/EN) се сменя горе вдясно.</p>`],
['Твоите данни остават при теб.',`<div class="cards"><div class="card"><span class="tag">СЪХРАНЕНИЕ</span><h3>Само локално</h3><p>Всичко е в <code>chrome.storage.local</code> на твоя браузър. Няма сървър, акаунт, аналитика или синхронизация. Друг браузър или профил = отделни данни.</p></div><div class="card"><span class="tag">ДЕЙСТВИЯ</span><h3>Само наблюдава</h3><p>Добавката не натиска бутони, не сменя задачи и не пише нищо в Redstone или Ximble. Единствената промяна е иконката и заглавието на таба при сигнал.</p></div></div><div class="table-wrap"><table><thead><tr><th>Разрешение</th><th>Защо</th></tr></thead><tbody><tr><td>storage</td><td>да пази отчета локално</td></tr><tr><td>alarms</td><td>проверка всяка минута за край на смяна</td></tr><tr><td>offscreen</td><td>да пусне звуковия сигнал във фонов режим</td></tr><tr><td>notifications (по избор)</td><td>само ако включиш системното известие</td></tr><tr><td>достъп до redstone / ximble</td><td>да чете адреса и бутоните на тези два сайта</td></tr></tbody></table></div><div class="callout"><strong>Важно:</strong> премахването на добавката изтрива данните. Преди обновяване или премахване свали JSON архив от отчета.</div>`],
['Какво още не е покрито.',`<p>Това е тестова версия. Следните случаи са известни и ще се коригират след проверка на живо:</p><div id="openq"></div><div class="closing"><p>Видиш ли нещо странно, запиши адреса на страницата (ID-то може да се замени с XXX) и направи снимка. Това е най-бързият начин да се оправи.</p></div>`]]},
en:{nav:'CONTENTS',aside:'',foot:'User guide',items:['What TaskTime is','Where it works','How a task is detected','When a task is completed','Alerts and tab colour','Shift, breaks, overtime','Questions panel','The report (Dashboard)','Data and privacy','Known limitations'],badge:'',title:'Your working day.<br><em>Clearly measured.</em>',lead:'TaskTime is a browser extension for Chrome and Opera. It detects the tasks you do in Redstone and your shifts in Ximble on its own, and shows a personal report: how many tasks, how long each took, breaks and overtime. Everything stays in your browser.',meta:['Google Chrome + Opera','Български / English','No server · local data'],stats:[['4','buttons finish a task'],['3','alert stages: 🟢 🟠 🔴'],['0','data sent anywhere']],sections:[
['A personal log that fills itself in.',`<p>Redstone tasks arrive one after another and the official report comes later. TaskTime gives you your own clear history the same day: what you completed, how long each took and how your shift went.</p><div class="cards"><div class="card"><span class="tag">TASKS</span><h3>Automatic detection</h3><p>The extension recognises a task from the page address (league, type, ID) and measures time while it is open. You press nothing extra.</p></div><div class="card"><span class="tag">SHIFT</span><h3>Working time from Ximble</h3><p>Clock In and Clock Out in Ximble define the start, breaks and end of the shift. The extension only asks what it cannot know.</p></div><div class="card"><span class="tag">ALERTS</span><h3>Never miss a task</h3><p>A sound and a coloured tab icon when a new task arrives or when Redstone asks “Are you still active?”.</p></div><div class="card"><span class="tag">REPORT</span><h3>Statistics by type</h3><p>Count, fastest, slowest, average and total duration per task type, for any period, with CSV export.</p></div></div><div class="callout">TaskTime times are the moments the extension <strong>observed</strong> an event. It is a personal log, not the employer’s official timer. Small differences are normal.</div>`],
['Two sites, each with its role.',`<div class="cards"><div class="card"><span class="tag">01 / TASKS</span><h3>redstone.secondspectrum.com</h3><p>A task is recognised from the address:</p><p><code>/global-tasks/&lt;league&gt;/&lt;type&gt;/&lt;ID&gt;</code></p><p>Example: <code>/global-tasks/uefa/single_player/8c3b492f-…</code></p><ul><li><strong>League</strong>: any league after <code>/global-tasks/</code> is accepted, including new ones (dsl, efl, football, football-delayed, ligue1, ligue2, lkl, uefa…).</li><li><strong>Type</strong>: ball, player, single_player, live_dead, lineup, reid, away, home, refs. An unknown type is recorded as <code>other</code>, not lost.</li><li><strong>ID</strong>: letters, digits, “-” and “_”.</li></ul></div><div class="card"><span class="tag">02 / WORKING TIME</span><h3>app.ximble.com</h3><p>The extension checks which button is visible: <strong>Clock Out</strong> visible = on shift; <strong>Clock In</strong> visible = off shift.</p><p>A state is accepted after it is stable for 2 seconds, so loading moments are ignored.</p></div></div><div class="callout"><strong>Pages that are NOT tasks:</strong> the waiting screen <code>/global-tasks/&lt;league&gt;/next</code> (“no tasks available, waiting”) and the Config, Mercury, Generate, Filters, Summary, Timing and Queue menus. Other domains (e.g. redstone-dev) are not tracked at all.</div><p>Both sites must be open in the <strong>same browser and profile</strong> where the extension is installed. Keep Ximble open in its own tab during the shift.</p>`],
['From opening to finishing a task.',`<div class="flow"><div class="step"><h3>1. The task opens</h3><p>As soon as the address is a task, recording starts: league, type, ID, start time. Auto Advance, clicks and scrubbing are actions inside the same task.</p></div><div class="step"><h3>2. Time accumulates</h3><p>While the tab is open the extension checks in every 15 seconds. If more than 45 seconds pass between check-ins (computer asleep, browser paused), that time is NOT counted; a “gap” is recorded.</p></div><div class="step"><h3>3. You press a finish button</h3><p>One of four: <strong>Finish & Next</strong>, <strong>Finish & Exit</strong>, <strong>Clear Samples & Next</strong>, <strong>Clear Samples & Exit</strong>. Task time stops at the click.</p></div><div class="step"><h3>4. The page leaves the task</h3><p>To the next task, the waiting screen, or the tab closes. If this happens within 2 minutes of the click, the task is <strong>completed</strong>.</p></div></div><div class="callout"><strong>Reloading the page</strong> (e.g. when the buttons only spin and you need to refresh) does not break the task: same address and ID, time continues. A reload longer than 45 seconds records a gap.</div>`],
['Completed or “needs review”?',`<p>Every task ends with one of two statuses. Only <strong>completed</strong> tasks count in statistics.</p><div class="cards"><div class="card"><span class="tag">✓ COMPLETED</span><h3>Everything is clear</h3><ul><li>One of the four finish buttons was clicked,</li><li>the page left the task within 2 minutes,</li><li>no gap over 45 seconds,</li><li>the site showed no error after the click,</li><li>the same task (same ID) was not already completed.</li></ul></div><div class="card"><span class="tag">? NEEDS REVIEW</span><h3>Something is uncertain</h3><ul><li>No finish-button click (e.g. a moderator removed the task and you pressed a plain Next/Exit),</li><li>leaving more than 2 minutes after the click,</li><li>a time gap,</li><li>a site error,</li><li>the same ID opened again,</li><li>the same task open in two tabs.</li></ul><p>In the report you <strong>confirm</strong> or <strong>exclude</strong> them with one button. The correction keeps the original reason.</p></div></div><div class="callout">The extension icon shows “!” when tasks need review.</div>`],
['Sound and colour when you need to look.',`<p>The extension changes the icon and title of the Redstone tab and plays a short two-tone chime. The icon and title return to normal as soon as the alert stops.</p><div class="table-wrap"><table><thead><tr><th>Stage</th><th>When</th><th>Tab</th><th>Sound</th><th>Stops</th></tr></thead><tbody><tr><td>🟢 Green</td><td>New task while the tab is NOT focused</td><td>green dot, title blinks “🟢 New task”</td><td>1 chime</td><td>when you return to the tab</td></tr><tr><td>🟠 Orange</td><td>Redstone shows “Are you still active?”</td><td>orange dot, “🟠 Not Active 13 sec.”</td><td>1 chime / s</td><td>dialog disappears</td></tr><tr><td>🔴 Red</td><td>5 seconds or less left</td><td>red dot, “🔴 Not Active 4 sec.”</td><td>2 chimes / s</td><td>dialog disappears</td></tr></tbody></table></div><p class="caption">“Focused” means the tab is active AND the browser window is in front. Minimised browser, another tab or another app = not focused.</p><div class="cards" style="margin-top:20px"><div class="card"><h3>Settings (in the report)</h3><ul><li><strong>Sound alert</strong> — on/off (on by default). Turns off sound only; the tab colour remains.</li><li><strong>Volume</strong> and a <strong>“Test sound”</strong> button.</li><li><strong>System notification</strong> — off by default. Turning it on asks the browser for permission. Shows league and type; clicking returns you to the tab.</li></ul></div><div class="card"><h3>How “Are you still active?” is detected</h3><p>By the dialog text; seconds are read from “…in <strong>13</strong> seconds”. Works mid-task too, not only after a new task. Orange and red sound even when the window is focused — if you don’t react, you’re probably away from the computer.</p></div></div>`],
['One logical shift, with every interruption.',`<div class="flow"><div class="step"><h3>Clock In</h3><p>A shift starts. The extension asks “What time does your shift end?”. For overnight shifts (20:00 → 02:00) the end is automatically the next day and the date is shown.</p></div><div class="step"><h3>Clock Out</h3><p>Question: “Taking a break or finishing work?”. <strong>Break</strong>: the shift continues; the next Clock In resumes it. <strong>Finish</strong>: the shift closes at the Clock Out moment.</p></div><div class="step"><h3>Planned end passes</h3><p>If you are still clocked in: “Your planned shift has ended. Are you still working?” → <strong>Continue with overtime</strong> or <strong>Finish work</strong>.</p></div><div class="step"><h3>“Finish” without Clock Out</h3><p>Reminder: “Clock Out in Ximble to confirm the end.” A shift is never closed by the clock alone.</p></div></div><div class="callout">You can answer later: the time of the <strong>event</strong> is recorded, not of the answer. If you answer “Finish” after you have already resumed work, the later period becomes a separate shift. If you open Ximble when the shift has already started, the start is when the extension first saw it.</div><p><strong>The extension icon</strong> shows the state: 🟢 green = on shift, 🟠 orange = on break, 🔴 red = off shift. A number on it = pending questions.</p>`],
['A question stays until you answer.',`<p>Questions appear in a small panel in the top-left corner of Redstone and Ximble, and in the report. The panel does not steal focus or block work — answer when convenient.</p><div class="panel"><strong>Taking a break or finishing work?</strong><p>This question stays until answered. The event time is preserved.</p><div class="actions"><span class="example-action">Take a break</span><span class="example-action">Finish work</span></div></div><p>Question kinds: shift end time, break/finish on Clock Out, overtime after the planned end, Clock Out reminder. The “Report” button in the panel opens the full report.</p>`],
['Everything in one place.',`<p>Clicking the TaskTime icon in the browser toolbar opens the report. It contains:</p><div class="cards"><div class="card"><h3>New task alert</h3><p>Sound and notification settings (see above).</p></div><div class="card"><h3>Statistics</h3><p>Choose a period (from–to). Per type: count, fastest, slowest, average, total. Only completed tasks count, by completion date.</p></div><div class="card"><h3>Shifts</h3><p>Start, end, working time, breaks, planned end and time after it, whether you chose overtime.</p></div><div class="card"><h3>Review + History</h3><p>Uncertain tasks with “Confirm”/“Exclude” buttons, and a full list of all tasks with ID, time and gap count.</p></div></div>${report('en')}<p style="margin-top:18px"><strong>Export:</strong> a <em>CSV</em> of the period’s statistics (opens in Excel, includes time zone) and a <em>JSON backup</em> of all data. Average = total time ÷ completed count. Switch language (БГ/EN) at the top right.</p>`],
['Your data stays with you.',`<div class="cards"><div class="card"><span class="tag">STORAGE</span><h3>Local only</h3><p>Everything is in your browser’s <code>chrome.storage.local</code>. No server, account, analytics or sync. Another browser or profile = separate data.</p></div><div class="card"><span class="tag">ACTIONS</span><h3>Observe only</h3><p>The extension never clicks buttons, changes tasks or writes anything to Redstone or Ximble. Its only visible change is the tab icon and title during an alert.</p></div></div><div class="table-wrap"><table><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td>storage</td><td>keep the report locally</td></tr><tr><td>alarms</td><td>check every minute for shift end</td></tr><tr><td>offscreen</td><td>play the alert sound in the background</td></tr><tr><td>notifications (optional)</td><td>only if you enable the system notification</td></tr><tr><td>access to redstone / ximble</td><td>read the address and buttons of these two sites</td></tr></tbody></table></div><div class="callout"><strong>Important:</strong> removing the extension deletes its data. Download a JSON backup from the report before updating or removing it.</div>`],
['What is not covered yet.',`<p>This is a beta. The following cases are known and will be adjusted after live testing:</p><div id="openq"></div><div class="closing"><p>If something looks wrong, note the page address (the ID can be replaced with XXX) and take a screenshot. That is the fastest way to get it fixed.</p></div>`]]}};
function report(lang){const bg=lang==='bg';const rows=[['ball',30,'1:12','4:38','2:30','1:15:00'],['player',20,'2:05','6:10','4:00','1:20:00'],['single_player',40,'0:48','3:15','1:45','1:10:00'],['live_dead',15,'1:30','5:20','3:00','0:45:00'],['lineup',10,'2:10','7:05','4:30','0:45:00'],['reid',12,'1:15','4:50','2:30','0:30:00'],['away',8,'1:05','3:40','2:00','0:16:00'],['home',9,'0:55','3:30','2:00','0:18:00'],['refs',6,'1:20','4:10','2:40','0:16:00'],['other',0,'—','—','—','0:00:00']];const head=bg?['Тип','Брой','Най-бърза','Най-бавна','Средно','Общо']:['Type','Count','Fastest','Slowest','Average','Total'];return `<div class="table-wrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}<tr><td>${bg?'Общо':'Total'}</td><td>150</td><td>—</td><td>—</td><td>2:38</td><td>6:35:00</td></tr></tbody></table></div><p class="caption">${bg?'ПРИМЕР · 7 ноември 2026 · Продължителности м:с; общо ч:м:с. Общото средно е претеглено и закръглено.':'EXAMPLE · 7 November 2026 · Durations m:ss; totals h:mm:ss. Overall average is weighted and rounded.'}</p>`}
function questions(lang){const bg=lang==='bg';const q=bg?[
['Отворено','LD (Live & Dead) и AE (Auto-Eventing)','Работят през целия мач по линк от Match Lead, без бутони Finish & Next/Exit. Ако адресът им е във формата на задача, ще се запишат като дълга задача „за преглед“, а редуването с REID в друг таб може да създаде фалшиви задачи. Трябва реален адрес, за да се изключат или броят отделно.'],
['Отворено','Задача, премахната от модератор','Прозорецът „задачата е премахната“ с бутони Next/Exit не се разпознава; задачата отива „за преглед“. Може да се засича автоматично, ако имаме точния текст.'],
['Отворено','Ръчен REID','Страницата е на redstone-dev и не се следи. Ако се появи на основния сайт, ще се изключи.'],
['Известно','Opera и звукът във фонов режим','Звукът се пуска чрез offscreen документ (Chrome). Ако Opera не го поддържа, сигналът се пуска от страницата и браузърът може да го блокира без скорошен клик.'],
['Известно','Разпознаване по английски текст','Бутоните Finish/Clear Samples, Clock In/Out и „Are you still active?“ се разпознават по точния английски текст. Ако сайтът го смени, засичането спира.'],
['Известно','Без синхронизация и норми','Данните не се пренасят между браузъри/профили. Няма „в норма / извън норма“, XLSX и възстановяване от JSON архив.']]:[
['Open','LD (Live & Dead) and AE (Auto-Eventing)','They run for a whole match via a Match Lead link, with no Finish & Next/Exit. If their address looks like a task, they become a long “needs review” task, and alternating with REID in another tab may create false tasks. A real address is needed to exclude or count them separately.'],
['Open','Task removed by a moderator','The “task removed” dialog with Next/Exit is not recognised; the task goes to review. It can be detected automatically once we have the exact text.'],
['Open','Manual REID','The page is on redstone-dev and is not tracked. If it appears on the main site it will be excluded.'],
['Known','Opera and background sound','Sound plays through an offscreen document (Chrome). If Opera lacks it, the chime plays from the page and the browser may block it without a recent click.'],
['Known','Detection by English text','Finish/Clear Samples, Clock In/Out and “Are you still active?” are matched by exact English text. If the site changes it, detection stops.'],
['Known','No sync or targets','Data does not move between browsers/profiles. No “on/off target”, XLSX or restore from JSON backup yet.']];return q.map((x,i)=>`<details ${i===0?'open':''}><summary><span class="status ${x[0]==='Отворено'||x[0]==='Open'?'pending':''}">${x[0]}</span> &nbsp; ${x[1]}</summary><p>${x[2]}</p></details>`).join('')}
function render(lang){const d=data[lang]||data.bg;document.documentElement.lang=lang;document.title=lang==='bg'?'TaskTime — Ръководство':'TaskTime — User guide';document.getElementById('navlabel').textContent=d.nav;document.getElementById('asideNote').innerHTML=d.aside;document.getElementById('foot').textContent=d.foot;document.getElementById('nav').innerHTML=d.items.map((x,i)=>`<a href="#s${i}">${String(i+1).padStart(2,'0')} &nbsp; ${x}</a>`).join('');document.getElementById('main').innerHTML=`<div class="hero"><span class="pill">${d.badge}</span><h1>${d.title}</h1><p class="lead">${d.lead}</p><div class="hero-meta">${d.meta.map(x=>`<span>${x}</span>`).join('')}</div></div><div class="summary">${d.stats.map(x=>`<div><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('')}</div>${d.sections.map((x,i)=>`<section id="s${i}"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${d.items[i]}</span><h2>${x[0]}</h2>${x[1]}</section>`).join('')}`;{const o=document.getElementById('openq');if(o)o.innerHTML=questions(lang)}document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));try{localStorage.setItem('tasktime-language',lang)}catch{} }
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>render(b.dataset.lang)));let initial='bg';try{initial=localStorage.getItem('tasktime-language')||'bg'}catch{}render(initial);
